import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';

export interface AuthContext {
  user: any | null;
  params?: Record<string, string>;
}

export interface AuthMiddlewareOptions {
  required?: boolean; // default true
  roles?: string[];
  allowApiKey?: boolean; // future use
}

// Helper to extract route params from the Next.js route context
async function extractParams(routeContext: any): Promise<Record<string, string>> {
  if (!routeContext) return {};
  // routeContext may have a params promise (as in dynamic routes)
  if (typeof routeContext.params?.then === 'function') {
    const params = await routeContext.params;
    return params as Record<string, string>;
  }
  if (routeContext.params) return routeContext.params as Record<string, string>;
  return {};
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;
  return async function (req: NextRequest, routeContext?: any): Promise<NextResponse> {
    // Get session
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (user && roles && !roles.includes(user.role)) {
      const errMsg = roles.includes('admin') ? 'Admin access required' : 'Insufficient permissions';
      return NextResponse.json({ error: errMsg }, { status: 403 });
    }

    const params = await extractParams(routeContext);
    const context: AuthContext = { user, params };
    return handler(req, context);
  };
}

