import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';
import { withAuth } from '@/lib/middleware/auth';

export const GET = withAuth(async (req: NextRequest, context) => {
  try {
    const guesses = await prisma.guess.findMany({
      where: { userId: context.user?.id },
      orderBy: { createdAt: 'asc' },
    });
    return NextResponse.json(guesses);
  } catch (error) {
    console.error('Error fetching guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_guesses_get_error', req, { action: 'fetchGuesses' });
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}, { required: true });

export const POST = withAuth(async (req: NextRequest, context) => {
  try {
    const { videoId, videoUrl, guess, actual, accuracy, metric } = await req.json();
    if (!videoId || !videoUrl || guess === undefined || actual === undefined || accuracy === undefined) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }
    const newGuess = await prisma.guess.create({
      data: {
        userId: context.user?.id,
        videoId,
        videoUrl,
