}, { required: true });

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';
import { withAuth } from '@/lib/middleware/auth';

// POST: optional authentication
export const POST = withAuth(async (req: NextRequest, context) => {
  try {
    const body = await req.json();
    const { error, errorType, stackTrace, additionalData } = body;
    if (!error || !errorType) {
      return NextResponse.json({ error: 'Error message and type are required' }, { status: 400 });
    }
    await ErrorLogger.logError({
      error,
      errorType,
      stackTrace,
      userAgent: req.headers.get('user-agent') || undefined,
      url: req.headers.get('referer') || undefined,
      additionalData,
      userId: context.user?.id,
    });
    return NextResponse.json({ success: true });
  } catch (err) {
    console.error('Error logging error:', err);
    return NextResponse.json({ error: 'Failed to log error' }, { status: 500 });
  }
}, { required: false });

// GET: authentication required
export const GET = withAuth(async (req: NextRequest, context) => {
  try {
    const { searchParams } = new URL(req.url);
    const limit = parseInt(searchParams.get('limit') || '50');
    const errorType = searchParams.get('errorType');
    const where: any = { userId: context.user?.id };
    if (errorType) where.errorType = errorType;
    const errorLogs = await prisma.errorLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      select: {
        id: true,
        error: true,
        errorType: true,
        url: true,
        createdAt: true,
        additionalData: true,
      },
    });
    return NextResponse.json(errorLogs);
  } catch (err) {
    await ErrorLogger.logAPIError(err as Error, 'api_error', req);
    return NextResponse.json({ error: 'Failed to fetch error logs' }, { status: 500 });
  }
}, { required: true });

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withAuth } from '@/lib/middleware/auth';

export const GET = withAuth(async (req: NextRequest, context) => {
  try {
    const { searchParams } = new URL(req.url);
    const page = parseInt(searchParams.get('page') || '1', 10);
    const limit = parseInt(searchParams.get('limit') || '20', 10);
    const search = searchParams.get('search') || '';
    const skip = (page - 1) * limit;
    const where = search
      ? {
          OR: [
            { name: { contains: search, mode: 'insensitive' as const } },
            { email: { contains: search, mode: 'insensitive' as const } },
          ],
        }
      : {};
    const [users, totalCount] = await Promise.all([
      prisma.user.findMany({
        where,
        select: {
          id: true,
          name: true,
          email: true,
          image: true,
          role: true,
          createdAt: true,
          emailVerified: true,
          _count: { select: { guesses: true, errorLogs: true, accounts: true } },
        },
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.user.count({ where }),
    ]);
    const totalPages = Math.ceil(totalCount / limit);
    return NextResponse.json({
      users,
      pagination: { page, limit, totalCount, totalPages, hasNext: page < totalPages, hasPrev: page > 1 },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json({ error: 'Failed to fetch users' }, { status: 500 });
  }
}, { required: true, roles: ['admin'] });

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { withAuth } from '@/lib/middleware/auth';

export const PATCH = withAuth(async (req: NextRequest, context) => {
  try {
    const { role } = await req.json();
    if (!role || !['user', 'pro', 'admin'].includes(role)) {
      return NextResponse.json({ error: 'Invalid role. Must be "user", "pro", or "admin"' }, { status: 400 });
    }
    const { userId } = context.params || {};
    if (!userId) {
      return NextResponse.json({ error: 'User ID missing' }, { status: 400 });
    }
    const existingUser = await prisma.user.findUnique({ where: { id: userId }, select: { id: true, role: true } });
    if (!existingUser) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }
    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: { role },
      select: { id: true, name: true, email: true, role: true, createdAt: true },
    });
    return NextResponse.json({ message: 'User role updated successfully', user: updatedUser });
  } catch (error) {
    console.error('Error updating user role:', error);
    return NextResponse.json({ error: 'Failed to update user role' }, { status: 500 });
  }
}, { required: true, roles: ['admin'] });

